#include <iostream>

struct Base {
  virtual void name() const { std::cout << "B"; }
};

struct Derived : Base {
  void name() const override { std::cout << "D"; }
};

void by_value(Base value) { value.name(); }
void by_ref(const Base& value) { value.name(); }

int main() {
  Derived object;
  by_value(object);
  by_ref(object);
}
